override fun onReceive(context: Context, intent: Intent) {
    if (intent.action != Intent.ACTION_BOOT_COMPLETED) return
    val pendingResult = goAsync()
    val appContext = context.applicationContext
    CoroutineScope(Dispatchers.IO).launch {
        try {
            val database = AppDatabase.getDatabase(appContext)
            val now = System.currentTimeMillis()
            val pending = database.doseLogDao().getPendingReminders(now)
            for (doseLog in pending) {
                val medication = database.medicationDao().getById(doseLog.medicationId) ?: continue
                val nextEligible = doseLog.nextEligibleAtEpochMillis ?: continue
                val (title, text) = ReminderMessage.build(medication.name, nextEligible)
                ExactAlarmScheduler.schedule(appContext, doseLog.id, nextEligible, title, text)
            }
        } finally {
            pendingResult.finish()
        }
    }
}
